"""Completed-candle event cooldown with volatility and structure gates."""
import pandas as pd
def evaluate_event_cooldown(candles,event,volatility,structure,config=None):
    cfg=(config or {}).get("cooldown",config or {});minimum=int(cfg.get("minimum_completed_m5_candles",3));rows=candles.copy() if candles is not None else pd.DataFrame();rows=rows[rows.complete.astype(bool)] if "complete" in rows else rows
    if not event:return {"active":False,"started_at":None,"completed_candles_elapsed":0,"minimum_required_candles":minimum,"minimum_candles_passed":False,"volatility_stabilized":False,"fresh_swings_available":False,"fresh_structure_available":False,"no_new_event":True,"data_quality_passed":bool(len(rows)),"release_allowed":False,"reasons":["No locked event."]}
    after=rows[rows.time>pd.Timestamp(event["completed_at"])] if "time" in rows else rows.iloc[0:0];vol_ok=bool(volatility.get("release_allowed"));structure_ok=bool(structure.get("formed_after_event"));release=len(after)>=minimum and vol_ok and structure_ok
    minimum_ok=len(after)>=minimum;swings_ok=bool(structure.get("fresh_swings_available",structure_ok));no_new=not bool(structure.get("new_event_detected"));data_ok=bool(len(rows));release=minimum_ok and vol_ok and swings_ok and structure_ok and no_new and data_ok
    return {"active":not release,"started_at":event["completed_at"],"completed_candles_elapsed":len(after),"minimum_required_candles":minimum,"minimum_candles_passed":minimum_ok,"volatility_stabilized":vol_ok,"fresh_swings_available":swings_ok,"fresh_structure_available":structure_ok,"no_new_event":no_new,"data_quality_passed":data_ok,"release_allowed":release,"reasons":[] if release else [label for passed,label in ((minimum_ok,"Minimum completed candles have not elapsed."),(vol_ok,"Volatility has not stabilized."),(swings_ok,"Fresh post-event swings are unavailable."),(structure_ok,"Fresh post-event structure is unavailable."),(no_new,"A newer event replaced this cooldown."),(data_ok,"Completed candle data is unavailable.")) if not passed]}
